package utils;

import io.cucumber.java.Scenario;
import org.openqa.selenium.OutputType;
import org.openqa.selenium.TakesScreenshot;
import config.DriverFactory;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public class ScreenshotUtils {
    public static void captureScreenshot(String scenarioName) {
        TakesScreenshot ts = (TakesScreenshot) DriverFactory.getInstance().getDriver();
        File source = ts.getScreenshotAs(OutputType.FILE);
        String destination = "target/screenshots/" + scenarioName + ".png";
        try {
            Files.createDirectories(Paths.get("target/screenshots/"));
            Files.copy(source.toPath(), Paths.get(destination));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
