package config;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.firefox.FirefoxDriver;
import org.openqa.selenium.remote.DesiredCapabilities;
import org.openqa.selenium.remote.RemoteWebDriver;

import java.net.MalformedURLException;
import java.net.URL;
import java.util.concurrent.TimeUnit;

public class DriverFactory {
    private static DriverFactory instance;
    private WebDriver driver;

    private DriverFactory() {
        // Private constructor to prevent instantiation
    }

    public static synchronized DriverFactory getInstance() {
        if (instance == null) {
            instance = new DriverFactory();
        }
        return instance;
    }

    public WebDriver getDriver() {
        if (driver == null) {
            String browser = ConfigReader.getInstance().getProperty("browser");
            String remoteUrl = ConfigReader.getInstance().getProperty("remote.url");
            if (remoteUrl != null && !remoteUrl.isEmpty()) {
                try {
                    DesiredCapabilities capabilities = new DesiredCapabilities();
                    capabilities.setBrowserName(browser);
                    driver = new RemoteWebDriver(new URL(remoteUrl), capabilities);
                } catch (MalformedURLException e) {
                    throw new RuntimeException("Invalid remote URL", e);
                }
            } else {
                switch (browser.toLowerCase()) {
                    case "chrome":
                        System.setProperty("webdriver.chrome.driver", "path/to/chromedriver");
                        driver = new ChromeDriver();
                        break;
                    case "firefox":
                        System.setProperty("webdriver.gecko.driver", "path/to/geckodriver");
                        driver = new FirefoxDriver();
                        break;
                    default:
                        throw new RuntimeException("Browser not supported: " + browser);
                }
            }
            driver.manage().timeouts().implicitlyWait(10, TimeUnit.SECONDS);
        }
        return driver;
    }

    public void quitDriver() {
        if (driver != null) {
            driver.quit();
            driver = null;
        }
    }
}
