package hooks;

import config.ConfigReader;
import config.DriverFactory;
import io.cucumber.java.After;
import io.cucumber.java.Before;
import org.openqa.selenium.WebDriver;
import utils.ScreenshotUtils;

public class Hooks {
    private ConfigReader configReader = new ConfigReader();

    @Before(order = 1)
    public void initializeDriver() {
        String browser = configReader.getString("browser", "chrome");
        boolean headless = configReader.getBoolean("headless", false);
        DriverFactory.setBaseUrl(configReader.getString("base.url", "http://localhost"));
        DriverFactory.initializeDriver(browser, headless);
    }

    @After(order = 1)
    public void tearDown() {
        WebDriver driver = DriverFactory.getDriver();
        if (driver != null) {
            ScreenshotUtils.captureScreenshot(driver);
            DriverFactory.quitDriver();
        }
    }
}
